begin;
create extension if not exists pgtap;
select plan(22);
insert into qarar_core.organizations(id,code,name_ar) values('85000000-0000-0000-0000-000000000001','roles-ci','اختبار الأدوار');
insert into qarar_core.organizations(id,code,name_ar) values('85000000-0000-0000-0000-000000000040','roles-foreign','مؤسسة أخرى');
insert into auth.users(id,email) values('85000000-0000-0000-0000-000000000041','roles-foreign@test.local');
insert into qarar_iam.users(id,organization_id,email,full_name_ar,status) values('85000000-0000-0000-0000-000000000041','85000000-0000-0000-0000-000000000040','roles-foreign@test.local','حساب مؤسسة أخرى','active');
insert into auth.users(id,email) values('85000000-0000-0000-0000-000000000002','roles-admin@test.local'),('85000000-0000-0000-0000-000000000003','roles-invited@test.local'),('85000000-0000-0000-0000-000000000009','roles-other@test.local');
insert into qarar_iam.users(id,organization_id,email,full_name_ar,is_system_admin,status)
select id,'85000000-0000-0000-0000-000000000001',email,'اختبار',id='85000000-0000-0000-0000-000000000002'::uuid,case when id='85000000-0000-0000-0000-000000000003'::uuid then 'inactive' else 'active' end from auth.users where id in ('85000000-0000-0000-0000-000000000002','85000000-0000-0000-0000-000000000003','85000000-0000-0000-0000-000000000009');
insert into qarar_core.governance_unit_types(id,organization_id,code,name_ar,is_council_type) values('85000000-0000-0000-0000-000000000004','85000000-0000-0000-0000-000000000001','unit','وحدة',false);
insert into qarar_core.governance_units(id,organization_id,unit_type_id,code,name_ar,status) values('85000000-0000-0000-0000-000000000005','85000000-0000-0000-0000-000000000001','85000000-0000-0000-0000-000000000004','office','إدارة','active');
insert into qarar_iam.roles(id,organization_id,code,name_ar,role_scope) values('85000000-0000-0000-0000-000000000006','85000000-0000-0000-0000-000000000001','role-a','دور أول','governance_unit'),('85000000-0000-0000-0000-000000000007','85000000-0000-0000-0000-000000000001','role-b','دور ثان','governance_unit');
set local "request.jwt.claims"='{"sub":"85000000-0000-0000-0000-000000000002","role":"authenticated"}';
select lives_ok($$select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000003','add',null,null,'85000000-0000-0000-0000-000000000006','85000000-0000-0000-0000-000000000005',null,current_date,null,'85000000-0000-0000-0000-000000000020')$$,'add role to invited identity');
select lives_ok($$select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000003','add',null,null,'85000000-0000-0000-0000-000000000007','85000000-0000-0000-0000-000000000005',null,current_date,null,'85000000-0000-0000-0000-000000000021')$$,'add second role');
select is((select count(*) from qarar_iam.memberships where user_id='85000000-0000-0000-0000-000000000003'),2::bigint,'two independent roles');
select is((select status from qarar_iam.users where id='85000000-0000-0000-0000-000000000003'),'inactive','roles do not activate invitation');
select lives_ok($$select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000003','add',null,null,'85000000-0000-0000-0000-000000000006','85000000-0000-0000-0000-000000000005',null,current_date,null,'85000000-0000-0000-0000-000000000020')$$,'safe retry of add');
select is((select count(*) from qarar_iam.memberships where user_id='85000000-0000-0000-0000-000000000003'),2::bigint,'retry does not duplicate');
create temporary table selected_role as select id,updated_at from qarar_iam.memberships where user_id='85000000-0000-0000-0000-000000000003' and role_id='85000000-0000-0000-0000-000000000006';
select lives_ok($$select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000003','disable',(select id from selected_role),(select updated_at from selected_role))$$,'disable role only');
select is((select membership_status from qarar_iam.memberships where id=(select id from selected_role)),'inactive','disabled record retained');
select throws_ok($$select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000003','enable',(select id from selected_role),(select updated_at from selected_role))$$,'40001',null,'stale reactivation rejected');
select lives_ok($$select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000003','enable',(select id from selected_role),(select updated_at from qarar_iam.memberships where id=(select id from selected_role)))$$,'reactivate role');
select throws_ok($$select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000009','disable',(select id from selected_role),(select updated_at from selected_role))$$,'P0002',null,'cannot mutate another target membership');
select lives_ok($$select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000003','update',(select id from selected_role),(select updated_at from qarar_iam.memberships where id=(select id from selected_role)),'85000000-0000-0000-0000-000000000006','85000000-0000-0000-0000-000000000005','صفة جديدة',current_date,null)$$,'edit existing role in place');
select is((select membership_title from qarar_iam.memberships where id=(select id from selected_role)),'صفة جديدة','edited title persisted');
select throws_ok($$select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000003','add',null,null,'85000000-0000-0000-0000-000000000006','85000000-0000-0000-0000-000000000005',null,current_date,null,'85000000-0000-0000-0000-000000000023')$$,'23P01',null,'different request cannot duplicate overlapping role');
select is((select count(*) from qarar_iam.memberships where user_id='85000000-0000-0000-0000-000000000003'),2::bigint,'failed duplicate leaves history unchanged');
select ok((select is_system_admin from qarar_iam.users where id='85000000-0000-0000-0000-000000000002'),'actual administrator authority unchanged');
insert into qarar_iam.permissions(id,organization_id,code,module,action,context_scope,name_ar) values('85000000-0000-0000-0000-000000000030','85000000-0000-0000-0000-000000000001','roles_test.read','roles_test','read','governance_unit','قراءة اختبار');
insert into qarar_iam.role_permissions(organization_id,role_id,permission_id) values('85000000-0000-0000-0000-000000000001','85000000-0000-0000-0000-000000000006','85000000-0000-0000-0000-000000000030');
update qarar_iam.users set status='active' where id='85000000-0000-0000-0000-000000000003';
set local "request.jwt.claims"='{"sub":"85000000-0000-0000-0000-000000000003","role":"authenticated"}';
select ok(qarar_iam.has_permission('roles_test.read','85000000-0000-0000-0000-000000000005'),'active role grants only its contextual permission');
set local "request.jwt.claims"='{"sub":"85000000-0000-0000-0000-000000000002","role":"authenticated"}';
select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000003','disable',(select id from selected_role),(select updated_at from qarar_iam.memberships where id=(select id from selected_role)));
set local "request.jwt.claims"='{"sub":"85000000-0000-0000-0000-000000000003","role":"authenticated"}';
select isnt(qarar_iam.has_permission('roles_test.read','85000000-0000-0000-0000-000000000005'),true,'disabled role revokes its permission with second role intact');
set local "request.jwt.claims"='{"sub":"85000000-0000-0000-0000-000000000002","role":"authenticated"}';
select throws_ok($$select api_v2.get_user_roles_v2('85000000-0000-0000-0000-000000000041')$$,'P0002',null,'administrator cannot read foreign user roles');
select throws_ok($$select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000041','add',null,null,'85000000-0000-0000-0000-000000000006','85000000-0000-0000-0000-000000000005',null,current_date,null,'85000000-0000-0000-0000-000000000042')$$,'P0002',null,'administrator cannot modify foreign user roles');
set local "request.jwt.claims"='{"sub":"85000000-0000-0000-0000-000000000009","role":"authenticated"}';
select throws_ok($$select api_v2.get_user_roles_v2('85000000-0000-0000-0000-000000000003')$$,'42501',null,'ordinary user cannot read role management');
select throws_ok($$select api_v2.manage_user_role_v2('85000000-0000-0000-0000-000000000003','add',null,null,'85000000-0000-0000-0000-000000000006','85000000-0000-0000-0000-000000000005')$$,'42501',null,'ordinary user cannot assign');
select * from finish();
rollback;
